// Reviewed catalog-only adaptation of original AssetVault Add -> spawnObject.
export function attachNativeAssetLibrary({host,signal,onAdd}){
 const doc=host.ownerDocument;let disposed=false,generation=0,current=null;
 host.innerHTML='<h2>Current theme object catalog</h2><p>Add an independent instance at the world center, including after the room is empty. Current theme only; no asset downloads, autoplay or cross-theme imports. Adding explicitly adopts existing instance format v6 if needed.</p><label>Search current theme objects <input type="search" maxlength="200" data-asset-library-search placeholder="Name, shape or role"></label><label>Shape <select data-asset-library-shape><option value="">All shapes</option></select></label><label>Role <select data-asset-library-role><option value="">All roles</option></select></label><label>Order <select data-asset-library-order><option value="catalog">Catalog order</option><option value="name">Name A–Z</option><option value="name-desc">Name Z–A</option></select></label><p data-asset-library-summary aria-live="polite"></p><div data-asset-library-list></div><p role="status" data-asset-library-status></p>';
 const list=host.querySelector('[data-asset-library-list]'),summary=host.querySelector('[data-asset-library-summary]'),status=host.querySelector('[data-asset-library-status]'),search=host.querySelector('[data-asset-library-search]'),shape=host.querySelector('[data-asset-library-shape]'),role=host.querySelector('[data-asset-library-role]'),order=host.querySelector('[data-asset-library-order]');
 function refreshFacet(select,field,label,objects){const previous=select.value;select.replaceChildren();for(const value of ['',...new Set(objects.map(o=>String(o[field])))].sort((a,b)=>a.localeCompare(b))){const option=doc.createElement('option');option.value=value;option.textContent=value||label;select.append(option);}const selected=[...select.options].some(o=>o.value===previous)?previous:'';[...select.options].find(option=>option.value===selected)?.setAttribute('selected','');}
 function compareNames(a,b){const left=String(a.name).toLowerCase(),right=String(b.name).toLowerCase();return left<right?-1:left>right?1:0;}
 function render(){if(disposed||!current)return;const {key,name,objects,count}=current,token=++generation,terms=search.value.trim().toLowerCase().split(/\s+/).filter(Boolean),matches=objects.filter(o=>{const text=[o.name,o.shape,o.role].map(String).join(' ').toLowerCase();return (!shape.value||String(o.shape)===shape.value)&&(!role.value||String(o.role)===role.value)&&terms.every(term=>text.includes(term));});if(order.value==='name')matches.sort(compareNames);else if(order.value==='name-desc')matches.sort((a,b)=>compareNames(b,a));summary.textContent=String(name)+' · '+count+'/100 instances · '+matches.length+'/'+objects.length+' catalog objects';list.replaceChildren();for(const o of matches){const row=doc.createElement('div'),label=doc.createElement('span'),button=doc.createElement('button');label.textContent=String(o.name)+' · '+String(o.shape)+' · '+String(o.role)+' ';button.textContent='Add '+String(o.name);button.dataset.addCatalogObject=o.id;button.disabled=count>=100;button.addEventListener('click',()=>{if(disposed||token!==generation||!host.contains(button))return;try{const id=onAdd(key,o.id);status.textContent='Added independent instance '+id+'. Undo removes this addition.';}catch(e){status.textContent=String(e.message||'Add failed; no instance created.');}});row.append(label,button);list.append(row);}if(!matches.length){const empty=doc.createElement('p');empty.textContent='No matching objects in this theme. Change or clear the search and filters.';list.append(empty);}}
 function update({key,name,objects,count}){if(disposed)return;current={key,name,objects,count};refreshFacet(shape,'shape','All shapes',objects);refreshFacet(role,'role','All roles',objects);render();status.textContent=count>=100?'Instance limit reached. Remove an instance before adding.':'Choose an object to add; existing room content is retained.';}
 function dispose(){if(disposed)return;disposed=true;generation++;current=null;search.removeEventListener('input',render);for(const select of [shape,role,order])select.removeEventListener('change',render);signal?.removeEventListener('abort',dispose);host.replaceChildren();}search.addEventListener('input',render);for(const select of [shape,role,order])select.addEventListener('change',render);signal?.addEventListener('abort',dispose,{once:true});if(signal?.aborted)dispose();return{update,dispose};
}
